408			A^x_{[\operatorname{eval}_y(\cdot)_i = a_i]} \ot \Id_B \simeq_{\delta} \Id_A \ot G^{i,\,x}_{[\operatorname{eval}_y(\cdot) = a_i]}\,.
409		\end{equation}
410		% The source (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:465-495) prints the
411		% transposed pairing G^{k,x}_{g_1} ... G^{1,x}_{g_k} ... G^{k,x}_{g_1}, which is undefined
412		% when the outcome sets differ; the pairing below is the one of Fact 4.34 in the NEEXP
413		% source. The empty product for k = 0 is also made explicit here. See
414		% rem:ld-sandwich-indexing.
415		Define the POVM family $\{C^x_{g_1,\,g_2,\,\dots,\,g_k}\}$, for $x \in \mathcal X$, by
416		\[
417			C^x_{g_1,\,g_2,\,\dots,\,g_k} = G^{k,\,x}_{g_k} \cdots G^{2,\,x}_{g_2}\; G^{1,\,x}_{g_1}\; G^{2,\,x}_{g_2} \cdots G^{k,\,x}_{g_k}\,;
