260	\begin{lemma}[Fact 4.20 in \cite{Natarajan2018NEEXP}]\label{fact:add-a-proj}
261		\lean{MIPStarRE.QPBT.opFamilyDistSq_mul_left_le}
262		\leanok
263		\uses{def:povm-distance}
264		Let $\mathcal A, \mathcal B, \mathcal C$ be finite sets, and let $\mu$ be a distribution over question pairs $(x,y)$. Let $\{A^x_{a,\,b}\}$ and $\{B^x_{a,\,b}\}$ be operators whose outcomes range over the product set $\mathcal A \times \mathcal B$. Suppose a set of operators $\{C^y_{a,\,c}\}$, whose outcomes range over the product set $\mathcal A \times \mathcal C$, satisfies the condition $\sum_c (C^y_{a,\,c})^\dagger C^y_{a,\,c} \le \Id$ for all $a$ and all $y$. If $A^x_{a,\,b} \approx_\delta B^x_{a,\,b}$ on average over $x$ sampled from the corresponding marginal of the distribution $\mu$, then $C^y_{a,\,c} A^x_{a,\,b} \approx_\delta C^y_{a,\,c} B^x_{a,\,b}$ on average over $(x,y)$ sampled from $\mu$.
265	\end{lemma}
266	\begin{proof}
267		Fix questions $x, y$ and answers $a \in \mathcal A$, $b \in \mathcal B$. Then
268		\begin{align*}
269			\sum_c \bigl\lVert (C^y_{a,\,c} A^x_{a,\,b} - C^y_{a,\,c} B^x_{a,\,b})\, \ket{\psi} \bigr\rVert^2
270			&= \bra{\psi} (A^x_{a,\,b} - B^x_{a,\,b})^\dagger \Bigl( \sum_c (C^y_{a,\,c})^\dagger C^y_{a,\,c} \Bigr) (A^x_{a,\,b} - B^x_{a,\,b}) \ket{\psi}\\
600	\end{definition}
601	
602	% Nonemptiness of the edge set is stated explicitly here: with E empty, m = k = 0 and the
603	% normalization 1/(2m-k) below is undefined. The source
604	% (references/qpbt-paper/07_types.tex:65-82) leaves this boundary hypothesis implicit.
605	\begin{definition}[Graph distribution]\label{def:graph-distribution}
606		Let $G = (U, E)$ be an undirected graph with vertex set $U$ and nonempty edge set $E$. Edges in $E$ are written as multisets $\{u, v\}$ of two vertices; the case $u = v$ represents a self-loop. Suppose there are $m \ge 1$ edges, $k$ of which are self-loops. Then the \emph{graph distribution $\mu_G$ of $G$} is the distribution over $U \times U$ such that for every $(u,v) \in U \times U$,
607		\[
608			\mu_G(u, v) =
609			\begin{cases}
610				1/(2m-k) & \text{if } \{u,v\} \in E\,,\\
611				0 & \text{otherwise}\,.
612			\end{cases}
613		\]
614		This is identical to the uniform distribution over ordered pairs $(u,v) \in U \times U$ such that $\{u,v\} \in E$: each edge that is not a self-loop contributes two ordered pairs, and each self-loop contributes one, whence the normalization $2m-k$.
615	\end{definition}
